#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    for (char m : {'T', 'F'}) {
        std::vector<uint8_t> ubjson_data = {'[', '$', static_cast<uint8_t>(m), '#', 'i', 0};
        try {
            auto j = nlohmann::json::from_ubjson(ubjson_data);
            std::cout << "UBJSON marker " << m << " valid: " << j.dump() << std::endl;
        } catch (const std::exception& e) {
            std::cout << "UBJSON marker " << m << " exception: " << e.what() << std::endl;
        }
    }
    return 0;
}
